<template>
  <template v-if="page==='screen'"><StatCards :items="cards"/><section class="content-grid"><article class="panel"><h2>AQI等级分布</h2><div v-for="item in levelRows" :key="item.label" class="metric-row"><AqiBadge :value="item.label"/><div><i :style="{width:item.percent+'%'}"></i></div><b>{{item.value}}</b></div></article><article class="panel"><h2>省份反馈热度</h2><div v-for="item in provinceRows" :key="item.label" class="province-row"><span>{{item.label}}</span><strong>{{item.value}}</strong><small>条监督反馈</small></div></article></section></template>
  <template v-else-if="page==='statistics'"><StatCards :items="cards"/><section class="panel"><h2>数据治理指标</h2><div class="indicator-grid"><article><span>城市网格覆盖</span><strong>{{stats.cityCoverage||0}}</strong><small>个城市网格接入系统</small></article><article><span>省级覆盖</span><strong>{{stats.provinceCoverage||0}}</strong><small>个省级行政区</small></article><article><span>闭环完成率</span><strong>{{completion}}%</strong><small>反馈完成现场检测</small></article><article><span>良好率</span><strong>{{goodRate}}%</strong><small>实测结果为优或良</small></article></div></section></template>
  <section v-else class="report-sheet"><p class="eyebrow">ENVIRONMENTAL DECISION BRIEF</p><h2>空气质量公众监督决策简报</h2><p class="report-date">生成时间：{{new Date().toLocaleString('zh-CN',{hour12:false})}}</p><div class="report-summary">系统累计接收公众反馈 <b>{{stats.feedbackTotal||0}}</b> 条，已完成现场实测 <b>{{stats.doneTotal||0}}</b> 条，其中污染等级数据 <b>{{stats.badTotal||0}}</b> 条。</div><h3>研判结论</h3><p>当前公众监督业务运行平稳，反馈信息已形成“公众上报、属地指派、网格核验、数据汇总、辅助决策”的闭环链路。</p><h3>治理建议</h3><ol><li>对轻度污染及以上区域增加巡检频次，关注施工扬尘和交通主干道周边。</li><li>优先使用本地网格员，任务积压时启动异地支援，缩短反馈处置周期。</li><li>持续对比公众预估等级与实测等级，提高公众监督数据的可信度。</li></ol><div class="report-sign">东软环保公众监督系统 · NEPV决策支持端</div></section>
</template>
<script setup>
import{computed,onMounted,ref}from'vue';import http from '../api/http';import AqiBadge from '../components/AqiBadge.vue';import StatCards from '../components/StatCards.vue';defineProps({page:String});const stats=ref({});const cards=computed(()=>[{label:'反馈总量',value:stats.value.feedbackTotal,icon:'fa-solid fa-message'},{label:'闭环完成',value:stats.value.doneTotal,icon:'fa-solid fa-circle-check'},{label:'污染数据',value:stats.value.badTotal,icon:'fa-solid fa-triangle-exclamation'},{label:'城市覆盖',value:stats.value.cityCoverage,icon:'fa-solid fa-city'}]);const toRows=obj=>{const entries=Object.entries(obj||{}),max=Math.max(1,...entries.map(x=>x[1]));return entries.map(([label,value])=>({label,value,percent:value/max*100}))};const levelRows=computed(()=>toRows(stats.value.levels));const provinceRows=computed(()=>toRows(stats.value.provinces));const completion=computed(()=>Math.round((stats.value.doneTotal||0)/Math.max(1,stats.value.feedbackTotal||0)*100));const goodRate=computed(()=>Math.round((stats.value.goodTotal||0)/Math.max(1,stats.value.doneTotal||0)*100));onMounted(async()=>stats.value=(await http.get('/stats')).data)
</script>
